#include "repository/PlatformRepository.h"

#include <stdexcept>

namespace arb {

PlatformRepository::PlatformRepository(OracleDatabase& database) : database_(database) {}

void PlatformRepository::createSchema() {
    Connection connection = database_.acquire();
    connection.execute(
        "BEGIN "
        "EXECUTE IMMEDIATE 'CREATE TABLE platform ("
        "platform_id NUMBER(19,0) GENERATED BY DEFAULT AS IDENTITY, "
        "name VARCHAR2(255 CHAR), "
        "PRIMARY KEY (platform_id))'; "
        "EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; "
        "END;");
}

std::optional<Platform> PlatformRepository::getPlatformByName(const std::string& name) {
    Connection connection = database_.acquire();
    Statement statement(connection, "SELECT platform_id, name FROM platform WHERE name = :name");
    statement.bindString("name", name);
    statement.execute();
    statement.defineInt(1);

    if (!statement.fetch()) {
        return std::nullopt;
    }

    return Platform(statement.getInt(1), statement.getString(2));
}

Platform PlatformRepository::save(const Platform& platform) {
    {
        Connection connection = database_.acquire();
        Statement statement(connection, "INSERT INTO platform (name) VALUES (:name)");
        statement.bindString("name", platform.name);
        statement.execute();
        connection.commit();
    }

    auto saved = getPlatformByName(platform.name);
    if (!saved) {
        throw std::runtime_error("Platform " + platform.name + " was not saved");
    }
    return *saved;
}

}
